"'$pats = '"'refill_controller\\.py','refill_controller_v2\\.py','refill_consumer_v2\\.py','refill_policy\\.toml','refill_state\\.json','refill_requests\\.json'
\"pattern,lineNumber,timestamp,preview\"
"'$n = 0
Get-Content -Path $path -ReadCount 500 | ForEach-Object {
  foreach ($line in $_) {
    $n++
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $m = $null
    foreach ($p in $pats) { if ($line -match $p) { $m = $p; break } }
    if (-not $m) { continue }
    $ts = '"''
    if ("'$line -match '"'\"timestamp\":\"(["'^"]+)"'"') { "'$ts = $Matches[1] }
    $prev = $line
    if ($prev.Length -gt 300) { $prev = $prev.Substring(0,300) }
    $prev = $prev -replace '"'\"',''; -replace ',',';'
    \""'$m,$n,$ts,$prev"
  }
}'

